package pl.zagranietyper;import org.junit.jupiter.api.Test;import pl.zagranietyper.repository.FootballSettlementRepository;import java.util.*;import java.util.concurrent.atomic.AtomicInteger;import static org.junit.jupiter.api.Assertions.*;
class FootballEventPlayerPositiveReviewedSnapshotTest {@Test void immutableBoundaryIsExact(){assertEquals(20,FootballEventPlayerPositiveReviewedSnapshot.APPROVED_IDS.size());assertEquals(20,FootballEventPlayerPositiveReviewedSnapshot.EXPECTED_W);assertEquals(0,FootballEventPlayerPositiveReviewedSnapshot.EXPECTED_L);assertEquals(0,FootballEventPlayerPositiveReviewedSnapshot.EXPECTED_V);assertEquals("f2e12390f70afa9da5dc57c8559c6cab0a2d1fba3a878ce1b19907fc8c2522ff",FootballEventPlayerPositiveReviewedSnapshot.EXPECTED_SHA256);}@Test void dryRunAndFailedGateNeverWrite(){AtomicInteger calls=new AtomicInteger();assertFalse(FootballEventPlayerPositiveCoverageDryRunMain.parseApply(new String[0]));assertNull(FootballEventPlayerPositiveCoverageDryRunMain.applyIfRequested(false,gate(true),List.of(),u->{calls.incrementAndGet();return success();}));assertThrows(IllegalStateException.class,()->FootballEventPlayerPositiveCoverageDryRunMain.applyIfRequested(true,gate(false),List.of(),u->{calls.incrementAndGet();return success();}));assertEquals(0,calls.get());}@Test void successfulGateDelegatesToExactApply(){AtomicInteger calls=new AtomicInteger();assertEquals(20,FootballEventPlayerPositiveCoverageDryRunMain.applyIfRequested(true,gate(true),List.of(),u->{calls.incrementAndGet();return success();}).updatedLegs());assertEquals(1,calls.get());}private static FootballEventPlayerPositiveReviewedSnapshot.Gate gate(boolean p){return new FootballEventPlayerPositiveReviewedSnapshot.Gate(20,20,0,0,"hash",Set.of(),Set.of(),p,p,p,p);}private static FootballSettlementRepository.ApplyResult success(){return new FootballSettlementRepository.ApplyResult(20,0,20,0,0,18,10,7,0,1,0);}}
